import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"文件系统包装器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/file-system-wrappers.md","filePath":"zh-Hans/deep-dive/file-system-wrappers.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/file-system-wrappers.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="文件系统包装器" tabindex="-1">文件系统包装器 <a class="header-anchor" href="#文件系统包装器" aria-label="Permalink to “文件系统包装器”">​</a></h1><p>包装器是围绕<a href="./file-system">文件系统</a> <code>Fs</code> 实例的工厂函数，拦截原始 FS 的行为。包装器函数在第一个参数接收原始 FS 并返回一个 <code>Fs</code>。覆盖型包装器返回带 <code>original</code> 成员的 <code>WrappedFs</code>；注入型包装器修改给定的 FS 并返回它。同一个 FS 实例可以叠加无限层覆盖包装器。</p><p>SDK 的规范 <code>prefixWrapper</code> API 和用法示例记录在<a href="./../development/file-system#prefixwrapper">开发：文件系统</a>。</p><p>没有任何包装器的根 FS 类型为 <code>RootFs</code>。<code>Fs</code> 是 <code>RootFs</code> 与 <code>WrappedFs</code> 的联合类型。</p><p>包装器有两类：</p><ul><li><strong>注入型包装器</strong>：通过直接重新赋值公开成员改变给定 FS 的部分方法。不产生新层。</li><li><strong>覆盖型包装器</strong>：最常见，在原始 FS 之上叠加一层新的包装。</li></ul><h2 id="内存控制包装器" tabindex="-1">内存控制包装器 <a class="header-anchor" href="#内存控制包装器" aria-label="Permalink to “内存控制包装器”">​</a></h2><ul><li>目标：本地和远端 <code>Fs</code></li><li>优先级：两者均为 <code>1000</code></li></ul><p>当前在 Bootstrap 中禁用，因为浏览器 GC 不可靠。有一条 <code>TODO</code> 计划在 Obsidian 最低 iOS 版本达到 16.4、<code>ResizableArrayBuffer</code> 可以手动释放内存后重新启用。启用时它同时作用于本地和远端，并接收一个共享的 <code>MemoryControlSharedState</code>，包含 <code>memoryConsumption</code>、<code>hangingOperations</code> 和 <code>maxMemory</code>。</p><p><code>hangingOperations</code> 池按传输大小（<code>stat.size</code>）降序保持排序，因此更长的传输先恢复。这让大文件分布到整个同步过程的前段，而不是被推迟到利用率低下的尾段。</p><p>只拦截 <code>read</code>、<code>readStream</code>、<code>write</code>、<code>writeStream</code> 调用：</p><ol><li><code>read()</code> 和 <code>readStream()</code> 到来时，预留 <code>min(stat.size, 16 MiB)</code>。内存不足时把操作放入排序池并延迟。失败时释放预留并恢复排队操作。消费量为零时，允许一个操作超过 <code>maxMemory</code>。</li><li><code>write()</code> 和 <code>writeStream()</code> 不预留内存。任一完成或失败时，释放 <code>min(stat.size, 16 MiB)</code>，内存允许时恢复排队的读操作。</li></ol><p>恢复时，包装器扫描整个池，纳入所有放得下的操作，跳过放不下的大操作。这种回填让剩余预算被较小的传输填满，而不是停在一个超大操作后面。</p><h2 id="优化包装器" tabindex="-1">优化包装器 <a class="header-anchor" href="#优化包装器" aria-label="Permalink to “优化包装器”">​</a></h2><ul><li>目标：本地和远端 <code>Fs</code></li><li>优先级：两者均为 <code>2000</code></li><li>机制：<code>setTimeout(..., 0)</code> 调度的原子队列</li></ul><h3 id="后端相关的优化" tabindex="-1">后端相关的优化 <a class="header-anchor" href="#后端相关的优化" aria-label="Permalink to “后端相关的优化”">​</a></h3><p>同步流程必须保持与后端无关，但最优执行策略各不相同（例如 WebDAV 需要按顺序创建父目录；S3 允许并发上传；Dropbox 把删除和移动合并进批量端点）。这个包装器在根层拦截 FS API 调用，在 promise 内重排、批量或调度执行，把逻辑与优化解耦。</p><p>后端可以用后端专属方法扩展 <code>RootFs</code>。批量优化器可以通过 <code>instanceof</code> 检查拿到 FS 并使用这些方法。</p><h3 id="操作合并" tabindex="-1">操作合并 <a class="header-anchor" href="#操作合并" aria-label="Permalink to “操作合并”">​</a></h3><p>合并使用零延迟定时器：修改调用（<code>write</code>、<code>writeStream</code>、<code>delete</code>、<code>mkdir</code>、<code>move</code>）作为 <code>InputAtom</code> 入队，定时器冲刷时把排队的原子交给注入的 <code>batchOptimizer</code>。只读调用（<code>read</code>、<code>readStream</code>、<code>getUid</code>、<code>stat</code>、<code>exists</code>、<code>list</code>）直接透传给原始 FS。<code>checkConnection</code> 属于远端后端条目，不属于 <code>Fs</code>。</p><p><strong>执行</strong>：</p><p>单原子队列直接执行该原子，不做批量。否则包装器把排队的原子交给注入的 <code>batchOptimizer</code>，优化器可以重排它们、替换为 <code>custom</code> 原子，或 resolve / reject 它们。排队的原子通过 <code>createCachedPromise()</code> 共享真实执行和延迟的 promise。</p><p>每个输入原子都有 <code>resolve</code> 和 <code>reject</code> 回调。优化器必须通过 reject 受影响的原子来传播操作失败，包括自定义原子替换它们、或批量操作返回逐键失败的情况。被移除的原子必须总是被 settle，否则它们原始的 promise 永远 pending。</p><h2 id="非对称存储包装器" tabindex="-1">非对称存储包装器 <a class="header-anchor" href="#非对称存储包装器" aria-label="Permalink to “非对称存储包装器”">​</a></h2><ul><li>目标：远端 <code>Fs</code></li><li>优先级：<code>11000</code>，仅在启用非对称存储时</li></ul><p>启用非对称存储时应用于远端 FS。它把层级化的文件和文件夹键压平为锚定键，委托之后还原层级化的状态和进度。文件夹由空文件表示。见<a href="./asymmetric-storage">非对称存储规范</a>。</p><h2 id="context-包装器" tabindex="-1">Context 包装器 <a class="header-anchor" href="#context-包装器" aria-label="Permalink to “Context 包装器”">​</a></h2><ul><li>目标：本地和远端 <code>Fs</code></li><li>优先级：本地 <code>20000</code>；远端 <code>20000</code>，启用非对称存储时远端再加 <code>10000</code></li></ul><p>拦截 <code>list()</code>、<code>stat()</code>、<code>write()</code>、<code>writeStream()</code>、<code>delete()</code>、<code>move()</code> 和 <code>mkdir()</code> 调用，在一个跨同步运行存活的 <code>uni-kv</code> 内存存储中构建尽力而为的已知状态副本。</p><p><code>read()</code> 和 <code>readStream()</code> 原样透传。FS 接口要求文件状态。</p><p>Bootstrap 使用这些存储：</p><ul><li><code>localContext20000</code></li><li><code>remoteContext10000</code></li><li><code>remoteContext20000</code></li></ul><p>行为：</p><ul><li><code>stat()</code> 时，把返回的状态 upsert 进 KV 存储</li><li><code>list()</code> 时，清空存储并按列表结果重建</li><li><code>write()</code> 或 <code>writeStream()</code> 时，把提供的状态与返回的 UID upsert</li><li><code>delete()</code> 时，删除记录。</li><li><code>move()</code> 时，把缓存的记录移到新键并修改它的 <code>key</code> 字段。</li><li><code>mkdir()</code> 时，upsert 文件夹记录。</li><li>所有内存数据库修改只在原始操作成功并返回之后发生。</li><li>包装器创建时，把它的标记与当前 FS UID 比较。不一致时清空存储并更新标记。</li></ul><h2 id="取消包装器" tabindex="-1">取消包装器 <a class="header-anchor" href="#取消包装器" aria-label="Permalink to “取消包装器”">​</a></h2><ul><li>目标：本地和远端 <code>Fs</code></li><li>优先级：两者均为 <code>3000</code></li></ul><p>第二个参数接收 <code>isCancelled: Ref&lt;boolean&gt;</code> 以检测同步取消。</p><p>拦截除 <code>getUid()</code> 外的所有 <code>Fs</code> 方法。转发前后检查取消状态，取消时以抛出异常包装所有方法调用。特殊情况：<code>read()</code> 和 <code>readStream()</code> 只在<strong>转发前</strong>检查取消，<code>write()</code> 和 <code>writeStream()</code> 只在<strong>转发后</strong>检查，以防止取消竞态阻塞内存控制计数器的释放。</p><h2 id="调试包装器" tabindex="-1">调试包装器 <a class="header-anchor" href="#调试包装器" aria-label="Permalink to “调试包装器”">​</a></h2><p>仅开发用的 <code>debugWrapper</code> 覆盖一个 FS 并记录每次方法调用。它从 SDK 开发入口导出，不属于运行时包装器链。</p><h3 id="前缀包装器" tabindex="-1">前缀包装器 <a class="header-anchor" href="#前缀包装器" aria-label="Permalink to “前缀包装器”">​</a></h3><p><code>prefixWrapper</code> 是可导入的 SDK 包装器，把一个目录暴露为另一个 <code>Fs</code> 的根：</p><p>它的类型是 <code>prefixWrapper(original: Fs, prefix: string): WrappedFs</code>。</p><p>包装器把 <code>prefix</code> 规范化为统一的目录键：Unicode 规范化、百分号编码的路径段被解码、空的斜杠段被移除、并加上尾部 <code>/</code>。委托文件系统操作时，它在前面加上规范化后的前缀。返回的状态键、列表结果和列表进度路径会去掉前缀；被包装的目录本身暴露为 <code>/</code>，并从递归列表结果中省略。返回的前缀之外的路径以错误拒绝。</p>`,44)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};